def main():
    print(f"📡 Ingesting {len(RAW_SURVEY)} Floor 2 survey fingerprints into MongoDB ({MONGODB_URI})...")
    client = MongoClient(MONGODB_URI, serverSelectionTimeoutMS=2500)
    db = client[DB_NAME]
    col = db["locations"]

    fingerprints = []
    mongo_docs = []

    for loc, x, y, bssids in RAW_SURVEY:
        pairs_text = " | ".join([f"{k}: {v}%" for k, v in bssids.items()])
        pairs_json = json.dumps({k: {"signal": f"{v}%", "frequency": "5 GHz" if "5F" in k else "2.4 GHz"} for k, v in bssids.items()})
        
        doc = {
            "location": loc,
            "x": x,
            "y": y,
            "floorId": "floor-2",
            "bssid_pairs_text": pairs_text,
            "bssid_pairs_json": pairs_json,
            "bssids": bssids,
            "count": len(bssids),
            "timestamp": "2026-09-08 18:22:00"
        }
        mongo_docs.append(doc)
        col.replace_one({"location": loc}, doc, upsert=True)

        fingerprints.append({
            "location": loc,
            "x": x,
            "y": y,
            "floorId": "floor-2",
            "bssids": bssids,
            "apCount": len(bssids)
        })

    print(f"✓ Upserted {len(mongo_docs)} records to MongoDB collection 'locations'.")

    # Save to data/sample/floor2-fingerprints.json
    os.makedirs("data/sample", exist_ok=True)
    with open("data/sample/floor2-fingerprints.json", "w") as f:
        json.dump(fingerprints, f, indent=2)
    print("✓ Saved data/sample/floor2-fingerprints.json")

if __name__ == "__main__":
    main()
